INSERT INTO fut_chem_reviews VALUES(1,18,'FC27','gk_ballplaying',21,23,'applied','실축 롱볼 15.5/90 → 킥 +6 · 다이빙 +9. Shield(반사신경 +9·킥 +6)도 같은 점수','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
INSERT INTO fut_chem_reviews VALUES(2,8,'FC27','fb_wingback',19,NULL,'applied','가장 약한 핵심이 가속 76·질주 77 → 속도 +6·+6. 슬라이딩 태클 PlayStyle에 슬라이딩 +9','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
INSERT INTO fut_chem_reviews VALUES(3,143,'FC27','cb_bpd',19,9,'keep','Aggressive 포커스·속도 74·76 → 튀어나간 뒤 복귀 속도(수비 스타일 중 속도는 Shadow뿐). 볼 플레잉 1위 Powerhouse는 패스 가중 탓','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
INSERT INTO fut_chem_reviews VALUES(4,9,'FC27','cb_bpd',19,9,'keep','속도 79·79가 약점이고 패스는 이미 85. 점유 위주 상대를 만나면 Powerhouse','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
