INSERT INTO fut_chem_reviews VALUES(6,14,'FC27','dm_holding',13,9,'applied','공 몰고 가기(드리블·민첩 +6)와 수비(+24)를 함께 올리는 유일한 스타일. 홀딩↔딥라잉을 자주 오가면 Powerhouse','reports/research/2026-11-05-bench-chem-review.md','2026-11-05');
INSERT INTO fut_chem_reviews VALUES(7,4,'FC27','dm_dlp',10,NULL,'applied','Engine은 딥라잉 핵심을 거의 안 올렸다(27 → 57). 패스·볼컨트롤·침착','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
