INSERT INTO fut_chem_reviews VALUES(9,16,'FC27','wm_insidefwd',17,11,'keep','속도형(가속 92→98)·실축 xG 0.14·전진 운반 83m/90. 커널 1위 Finisher는 결정력 가중 탓 — 철회. 오래 몰고 크로스까지면 Engine','reports/research/2026-11-05-xi-chem-review.md','2026-11-05');
INSERT INTO fut_chem_reviews VALUES(10,683,'FC27','cam_playmaker',10,7,'applied','실축 슈팅 3.7·크로스 0(90분당) · 볼컨트롤 첫 터치·공 밀착(A). LM 와이드 플레이메이커로 쓰면 Artist','reports/research/2026-11-05-manzambi-chem-artist-vs-maestro.md','2026-11-05');
